mapper.sql:
FROM nw_platform_members mFROM nw_tenant_members m
LEFT JOIN nw_foundation_member_profiles p ON p.scope_key=#{scope} AND p.member_id=m.id
WHERE truem.tenant_id::text=#{scope}
AND (m.username ILIKE '%'||#{keyword}||'%' OR p.display_name ILIKE '%'||#{keyword}||'%')

  AND (m.id::text=#{filter.memberId}
  OR p.department_id::text IN #{departmentId})

mapper.select:
SELECT m.id,m.username,coalesce(p.display_name,m.username) AS display_name,m.email,m.status,p.department_id,p.position_id,
  coalesce(p.authorization_version,1) AS authorization_version,coalesce(p.lock_version,1) AS lock_version,m.created_at
 ORDER BY m.id DESC LIMIT #{limit} OFFSET #{offset}

SELECT count(DISTINCT mr.member_id) FROM nw_foundation_member_roles mr
JOIN nw_foundation_roles r ON r.scope_key=mr.scope_key AND r.id=mr.role_id AND r.administrator AND r.enabled
JOIN nw_platform_members m ON m.id=mr.member_id
JOIN nw_tenant_members m ON m.id=mr.member_id AND m.tenant_id::text=#{scope}
WHERE mr.scope_key=#{scope} AND m.status='active' AND mr.member_id<>#{memberId}
